-- TRILHA — Etapa 1 do sistema de Classes
-- Estrutura completa da árvore (12 Iniciantes, 24 Competentes, 48 Proficientes e 96 Especialistas).
-- Fonte: TRILHA_arvore_classes_subclasses_ecos_competentes.xlsx

CREATE TABLE IF NOT EXISTS class_nodes (
  id text PRIMARY KEY,
  root_class text NOT NULL,
  stage text NOT NULL CHECK (stage IN ('Iniciante','Competente','Proficiente','Especialista')),
  stage_order integer NOT NULL CHECK (stage_order BETWEEN 1 AND 4),
  level_min integer NOT NULL CHECK (level_min BETWEEN 1 AND 20),
  level_max integer NOT NULL CHECK (level_max BETWEEN 1 AND 20 AND level_max >= level_min),
  name text NOT NULL,
  description text NOT NULL DEFAULT '',
  parent_id text REFERENCES class_nodes(id) ON DELETE RESTRICT,
  parent_name text,
  attribute_fixed text,
  attribute_alternative_a text,
  attribute_alternative_b text,
  attributes_base text,
  primary_skill text,
  secondary_skill text,
  primary_theme text,
  secondary_theme text,
  requirement_text text NOT NULL,
  requirements jsonb NOT NULL DEFAULT '{}'::jsonb,
  requirement_status text NOT NULL DEFAULT 'Definido',
  sort_order integer NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (root_class, name)
);

CREATE INDEX IF NOT EXISTS class_nodes_root_class_idx ON class_nodes(root_class);
CREATE INDEX IF NOT EXISTS class_nodes_parent_id_idx ON class_nodes(parent_id);
CREATE INDEX IF NOT EXISTS class_nodes_stage_idx ON class_nodes(stage, stage_order);
CREATE INDEX IF NOT EXISTS class_nodes_sort_order_idx ON class_nodes(sort_order);

ALTER TABLE class_nodes ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS class_nodes_select ON class_nodes;
CREATE POLICY class_nodes_select
ON class_nodes
FOR SELECT
TO anon, authenticated
USING (true);

-- Nesta etapa a árvore é somente de consulta no site.
-- Não são criadas policies de INSERT/UPDATE/DELETE pelo frontend.


